import React from 'react';
import { motion } from 'framer-motion';
import { Check, Star, Zap, Shield, ArrowLeft, CreditCard } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useBackHandler } from '../hooks/useBackHandler';
import { getDashboardPathForRole } from '../utils/backHandler';
import { getStoredSession } from '../utils/authSession';
import './Pricing.css';

const Pricing = () => {
  const navigate = useNavigate();

  useBackHandler(() => {
    const { role } = getStoredSession();
    if (role) {
      navigate(getDashboardPathForRole(role), { replace: true });
    } else {
      navigate('/');
    }
    return true;
  }, [navigate]);

  const plans = [
    {
      name: 'Gratuit',
      price: '0',
      icon: <Zap size={24} color="#64748B" />,
      features: ['Accès aux cours publics', '3 résumés IA / jour', 'Groupes publics', 'Annonces campus'],
      color: '#475569',
      btnText: 'Actuel',
      highlight: false
    },
    {
      name: 'Étudiant Premium',
      price: '2 500',
      icon: <Star size={24} color="var(--secondary)" />,
      features: ['Accès illimité aux corrigés', 'IA illimitée (Résumés & Quiz)', 'Mode Hors-ligne', 'Support prioritaire', 'Badges exclusifs'],
      color: 'var(--primary)',
      btnText: 'Devenir Premium',
      highlight: true
    },
    {
      name: 'Institutionnel',
      price: 'Sur devis',
      icon: <Shield size={24} color="var(--accent)" />,
      features: ['Accès pour toute la promotion', 'Tableau de bord délégué avancé', 'Modération IA personnalisée', 'Statistiques de réussite'],
      color: 'var(--accent)',
      btnText: 'Contacter l\'UL',
      highlight: false
    }
  ];

  // Animations classiques
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { 
      opacity: 1,
      transition: { staggerChildren: 0.2 }
    }
  };

  const cardVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: { 
      opacity: 1, 
      y: 0,
      transition: { duration: 0.6, ease: "easeOut" }
    }
  };

  return (
    <div className="pricing-page">
      <div className="pricing-bg-decor"></div>
      
      <header className="pricing-header">
        <button onClick={() => {
          const { role } = getStoredSession();
          if (role) navigate(getDashboardPathForRole(role), { replace: true });
          else navigate('/');
        }} className="btn-back">
          <ArrowLeft size={20} /> Retour au Dashboard
        </button>
      </header>

      <div className="container">
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="pricing-intro"
        >
          <span className="premium-badge">OFFRES EXCLUSIVES</span>
          <h1>Investissez dans votre Réussite</h1>
          <p>Choisissez le plan qui correspond à vos ambitions académiques.</p>
        </motion.div>

        <motion.div 
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="plans-grid"
        >
          {plans.map((plan, index) => (
            <motion.div 
              key={index}
              variants={cardVariants}
              className={`plan-card ${plan.highlight ? 'plan-highlight' : ''}`}
            >
              {plan.highlight && <div className="most-popular">RECOMMANDÉ</div>}
              <div className="plan-icon-wrapper" style={{ background: `${plan.color}15` }}>
                {plan.icon}
              </div>
              <h3 className="plan-name">{plan.name}</h3>
              <div className="plan-price">
                <span className="currency">{plan.price !== 'Sur devis' ? 'XOF' : ''}</span>
                <span className="amount">{plan.price}</span>
                <span className="period">{plan.price !== 'Sur devis' ? '/semestre' : ''}</span>
              </div>
              
              <ul className="plan-features">
                {plan.features.map((feature, fIndex) => (
                  <li key={fIndex}>
                    <Check size={18} color={plan.highlight ? 'var(--secondary)' : 'var(--accent)'} />
                    {feature}
                  </li>
                ))}
              </ul>

              <button 
                className={`btn-plan ${plan.highlight ? 'btn-plan-highlight' : ''}`}
                style={!plan.highlight ? { border: `2px solid ${plan.color}`, color: plan.color } : {}}
              >
                {plan.btnText}
              </button>
            </motion.div>
          ))}
        </motion.div>

        <motion.div 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1 }}
          className="payment-methods"
        >
          <p>Paiement sécurisé via :</p>
          <div className="methods-icons">
            <div className="method-tag">T-Money</div>
            <div className="method-tag">Flooz</div>
            <div className="method-tag">Carte Bancaire</div>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default Pricing;
